# Which vault key feeds which key of which Kubernetes Secret. The vault key is `KEY` in the
# operator's Touch ID vault namespace `movies` (kinowo's), or `<namespace>:KEY` for another one
# (`filmowo:` — filmowo keeps its own vault). NAMES ONLY -- the values never enter git. Pushed by infra/bin/push-k8s-secrets.
# The vault is the source of truth; the Secrets are copies (no more building them from .env.local).
#
# <namespace>/<secret>  <SECRET_KEY>  <VAULT_KEY>
# A row whose vault key does not exist yet is skipped (the Secret keeps its current value), so the
# map can list everything now and fill in as each credential is rotated.
kinowo/web-secrets      APPLICATION_SECRET            WEB_APPLICATION_SECRET
kinowo/web-secrets      GOOGLE_CLIENT_ID              GOOGLE_CLIENT_ID
kinowo/web-secrets      GOOGLE_CLIENT_SECRET          GOOGLE_CLIENT_SECRET
kinowo/web-secrets      FACEBOOK_APP_ID               FACEBOOK_APP_ID
kinowo/web-secrets      FACEBOOK_APP_SECRET           FACEBOOK_APP_SECRET
kinowo/web-secrets      MONGODB_URI                   MONGODB_URI
kinowo/web-secrets      OMDB_API_KEY                  OMDB_API_KEY
kinowo/web-secrets      SENTRY_DSN                    SENTRY_DSN
kinowo/web-secrets      TMDB_API_KEY                  TMDB_API_KEY
kinowo/worker-secrets   APPLICATION_SECRET            WORKER_APPLICATION_SECRET
kinowo/worker-secrets   MONGODB_URI                   MONGODB_URI
kinowo/worker-secrets   OMDB_API_KEY                  OMDB_API_KEY
kinowo/worker-secrets   SENTRY_DSN                    SENTRY_DSN
kinowo/worker-secrets   TMDB_API_KEY                  TMDB_API_KEY
kinowo/worker-secrets   ZYTE_API_KEY                  ZYTE_API_KEY
kinowo/worker-secrets   DECODO_PROXY_USER             DECODO_PROXY_USER
kinowo/worker-secrets   DECODO_PROXY_PASS             DECODO_PROXY_PASS
kinowo/worker-secrets   TELEGRAM_BOT_TOKEN            TELEGRAM_BOT_TOKEN
filmowo/filmowo-secrets APPLICATION_SECRET            filmowo:APPLICATION_SECRET
filmowo/filmowo-secrets GOOGLE_CLIENT_ID              filmowo:GOOGLE_CLIENT_ID
filmowo/filmowo-secrets GOOGLE_CLIENT_SECRET          filmowo:GOOGLE_CLIENT_SECRET
filmowo/filmowo-secrets FACEBOOK_APP_ID               filmowo:FACEBOOK_APP_ID
filmowo/filmowo-secrets FACEBOOK_APP_SECRET           filmowo:FACEBOOK_APP_SECRET
filmowo/filmowo-secrets TMDB_API_KEY                  filmowo:TMDB_API_KEY
filmowo/filmowo-secrets RAPIDAPI_KEY                  filmowo:RAPIDAPI_KEY
filmowo/filmowo-secrets TRAKT_KEY                     filmowo:TRAKT_KEY
filmowo/filmowo-secrets FILMOWO_PROXY_USER            filmowo:FILMOWO_PROXY_USER
filmowo/filmowo-secrets FILMOWO_PROXY_PASS            filmowo:FILMOWO_PROXY_PASS
filmowo/filmowo-secrets LITESTREAM_SECRET_ACCESS_KEY  filmowo:LITESTREAM_SECRET_ACCESS_KEY
monitoring/headlamp-oidc  client-secret                 GOOGLE_SSO_CLIENT_SECRET
